-- PitchPoint demo dataset: Brussels-Capital Region
--
-- Populates users, pitches and bookings with a large, realistic set of
-- football pitches spread across all 19 communes of the Brussels-Capital
-- Region, plus owner/player accounts and a spread of bookings.
--
-- All demo accounts share the password: password123
--
-- SAFE TO RE-RUN: wipes existing rows first (children before parents, to
-- respect foreign keys) and resets auto-increment counters, so running
-- this twice always leaves the same clean dataset rather than piling up
-- duplicates.
--
-- Usage:
--   mysql -u <user> -p pitchpoint < seed_brussels.sql

START TRANSACTION;

DELETE FROM bookings;
DELETE FROM pitches;
DELETE FROM users;
ALTER TABLE bookings AUTO_INCREMENT = 1;
ALTER TABLE pitches AUTO_INCREMENT = 1;
ALTER TABLE users AUTO_INCREMENT = 1;

-- ============================================================
-- Users: 6 owners (each managing a group of communes) + 5 players
-- ============================================================

-- Owner user ids are 1-6 (insertion order above), player ids are 7-11.

-- ============================================================
-- Pitches: 38 pitches, 2 per commune, across all 19 communes
-- ============================================================

-- Pitch ids are 1-38 in insertion order above.

-- ============================================================
-- Bookings: a spread of confirmed/cancelled bookings across players,
-- pitches and dates (past, present and future relative to seed time).
-- ============================================================

COMMIT;

-- Quick sanity check after running:
--   SELECT COUNT(*) FROM users;    -- 11
--   SELECT COUNT(*) FROM pitches;  -- 38
--   SELECT COUNT(*) FROM bookings; -- 19
